// Lane A packet parser. Uses fecim_pkg::crc8_byte.
// The response payload itself is generated by packet_tx/readout_ser.
module packet_parser import fecim_pkg::*; (
    input logic clk, rst_n,
    input logic [7:0] rx_data,
    input logic rx_valid,
    output logic bulk_we,
    output bulk_target_e bulk_target,
    output logic [15:0] bulk_addr,
    output logic [7:0] bulk_data,
    output logic cfg_we,
    output logic [7:0] cfg_addr,
    output logic [31:0] cfg_wdata,
    input logic [31:0] cfg_rdata,
    output logic start_compute,
    input logic compute_busy, compute_done,
    output logic rd_go, rd_argmax,
    output logic [COL_AW-1:0] rd_start,
    output logic [COL_AW:0] rd_count,
    output logic resp_valid,
    output logic [7:0] resp_cmd,
    output status_e resp_status,
    output logic [15:0] resp_len,
    input logic resp_ready,
    output logic [15:0] rx_byte_cnt, err_cnt,
    output logic err_latched
);
    pkt_state_e state;
    logic [7:0] command, crc;
    logic [15:0] payload_len, payload_idx, stream_addr;
    logic [7:0] small_payload [0:4];
    logic [31:0] timeout_count;
    logic wait_compute;
    logic [15:0] read_start_word, read_count_word;
    logic [15:0] next_length;
    logic is_bulk;
    status_e dispatch_status;

    assign next_length = {rx_data, payload_len[7:0]};
    assign is_bulk = (command == CMD_WRITE_WEIGHTS ||
                      command == CMD_WRITE_ACT || command == CMD_WRITE_ATTEN);
    // Keep the response asserted until packet_tx accepts it.
    // cfg_rdata is consumed by packet_tx via its own config read path.
    // The parser does not own response payload bytes.

    always_comb begin
        dispatch_status = ST_OK;
        case (command)
            CMD_WRITE_WEIGHTS, CMD_WRITE_ACT, CMD_WRITE_ATTEN:
                if (payload_len < 16'd3) dispatch_status = ST_BAD_LEN;
            CMD_SET_CONFIG:
                if (payload_len != 16'd5) dispatch_status = ST_BAD_LEN;
                else if (small_payload[0] > 8'h0C ||
                         small_payload[0] == REG_STATUS ||
                         small_payload[0] == REG_CYCLE_CNT)
                    dispatch_status = ST_ADDR_RANGE;
            CMD_GET_CONFIG:
                if (payload_len != 16'd1) dispatch_status = ST_BAD_LEN;
                else if (small_payload[0] > 8'h0C) dispatch_status = ST_ADDR_RANGE;
            CMD_COMPUTE, CMD_IDENTIFY, CMD_READ_ARGMAX:
                if (payload_len != 0) dispatch_status = ST_BAD_LEN;
            CMD_READ_RESULT: begin
                if (payload_len != 16'd4) dispatch_status = ST_BAD_LEN;
                else if (read_count_word == 0 || read_count_word > TILE_COLS ||
                         read_start_word >= TILE_COLS ||
                         (int'(read_start_word) + int'(read_count_word)) > TILE_COLS)
                    dispatch_status = ST_ADDR_RANGE;
            end
            default: dispatch_status = ST_UNKNOWN_CMD;
        endcase
        if (dispatch_status == ST_OK && compute_busy && command == CMD_COMPUTE)
            dispatch_status = ST_BUSY;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= PKT_HUNT;
            command <= 0;
            crc <= CRC_INIT;
            payload_len <= 0;
            payload_idx <= 0;
            stream_addr <= 0;
            timeout_count <= 0;
            wait_compute <= 0;
            read_start_word <= 0;
            read_count_word <= 0;
            bulk_we <= 0;
            bulk_target <= TGT_WEIGHTS;
            bulk_addr <= 0;
            bulk_data <= 0;
            cfg_we <= 0;
            cfg_addr <= 0;
            cfg_wdata <= 0;
            start_compute <= 0;
            rd_go <= 0;
            rd_argmax <= 0;
            rd_start <= 0;
            rd_count <= 0;
            resp_valid <= 0;
            resp_cmd <= 0;
            resp_status <= ST_OK;
            resp_len <= 0;
            rx_byte_cnt <= 0;
            err_cnt <= 0;
            err_latched <= 0;
            for (int i=0; i<5; i++) small_payload[i] <= 0;
        end else begin
            bulk_we <= 0;
            cfg_we <= 0;
            start_compute <= 0;
            rd_go <= 0;
            if (rx_valid) rx_byte_cnt <= rx_byte_cnt + 16'd1;
            if (state == PKT_HUNT || state == PKT_RESPOND || state == PKT_DISPATCH)
                timeout_count <= 0;
            else if (rx_valid) timeout_count <= 0;
            else timeout_count <= timeout_count + 32'd1;

            if (state != PKT_HUNT && state != PKT_RESPOND &&
                state != PKT_DISPATCH && timeout_count >= TIMEOUT_CYCLES-1) begin
                state <= PKT_HUNT;
                err_cnt <= err_cnt + 16'd1;
                err_latched <= 1;
            end else begin
                case (state)
                    PKT_HUNT: if (rx_valid && rx_data == SYNC_H2F) begin
                        state <= PKT_CMD;
                        crc <= CRC_INIT;
                        payload_len <= 0;
                        payload_idx <= 0;
                    end
                    PKT_CMD: if (rx_valid) begin
                        command <= rx_data;
                        crc <= crc8_byte(crc, rx_data);
                        state <= PKT_LEN0;
                    end
                    PKT_LEN0: if (rx_valid) begin
                        payload_len[7:0] <= rx_data;
                        crc <= crc8_byte(crc, rx_data);
                        state <= PKT_LEN1;
                    end
                    PKT_LEN1: if (rx_valid) begin
                        crc <= crc8_byte(crc, rx_data);
                        payload_len <= next_length;
                        if (next_length > MAX_PAYLOAD) begin
                            resp_cmd <= command;
                            resp_status <= ST_BAD_LEN;
                            resp_len <= 0;
                            resp_valid <= 1;
                            err_cnt <= err_cnt + 16'd1;
                            err_latched <= 1;
                            state <= PKT_RESPOND;
                        end else if (next_length == 0) state <= PKT_CRC;
                        else state <= PKT_PAYLOAD;
                    end
                    PKT_PAYLOAD: if (rx_valid) begin
                        crc <= crc8_byte(crc, rx_data);
                        if (payload_idx < 5) small_payload[payload_idx] <= rx_data;
                        if (payload_idx == 0) begin
                            stream_addr[7:0] <= rx_data;
                            read_start_word[7:0] <= rx_data;
                            cfg_addr <= rx_data;
                        end
                        if (payload_idx == 1) begin
                            stream_addr[15:8] <= rx_data;
                            read_start_word[15:8] <= rx_data;
                        end
                        if (payload_idx == 2) read_count_word[7:0] <= rx_data;
                        if (payload_idx == 3) read_count_word[15:8] <= rx_data;
                        if (is_bulk && payload_idx >= 2) begin
                            bulk_we <= 1;
                            bulk_target <= (command == CMD_WRITE_WEIGHTS) ? TGT_WEIGHTS :
                                           (command == CMD_WRITE_ACT) ? TGT_ACT : TGT_ATTEN;
                            bulk_addr <= stream_addr;
                            bulk_data <= rx_data;
                            stream_addr <= stream_addr + 16'd1;
                        end
                        payload_idx <= payload_idx + 16'd1;
                        if (payload_idx == payload_len - 1) state <= PKT_CRC;
                    end
                    PKT_CRC: if (rx_valid) begin
                        if (rx_data != crc) begin
                            resp_cmd <= command;
                            resp_status <= ST_CRC_ERR;
                            resp_len <= 0;
                            resp_valid <= 1;
                            err_cnt <= err_cnt + 16'd1;
                            err_latched <= 1;
                            state <= PKT_RESPOND;
                        end else state <= PKT_DISPATCH;
                    end
                    PKT_DISPATCH: begin
                        if (dispatch_status != ST_OK) begin
                            resp_cmd <= command;
                            resp_status <= dispatch_status;
                            resp_len <= 0;
                            resp_valid <= 1;
                            err_cnt <= err_cnt + 16'd1;
                            err_latched <= 1;
                            state <= PKT_RESPOND;
                        end else begin
                            resp_cmd <= command;
                            resp_status <= ST_OK;
                            resp_len <= 0;
                            case (command)
                                CMD_SET_CONFIG: begin
                                    cfg_we <= 1;
                                    cfg_wdata <= {small_payload[4],small_payload[3],small_payload[2],small_payload[1]};
                                end
                                CMD_COMPUTE: begin
                                    start_compute <= 1;
                                    wait_compute <= 1;
                                end
                                CMD_GET_CONFIG: resp_len <= 4;
                                CMD_IDENTIFY: resp_len <= 16;
                                CMD_READ_RESULT: begin
                                    rd_go <= 1;
                                    rd_argmax <= 0;
                                    rd_start <= read_start_word[COL_AW-1:0];
                                    rd_count <= read_count_word[COL_AW:0];
                                    resp_len <= read_count_word << 2;
                                end
                                CMD_READ_ARGMAX: begin
                                    rd_go <= 1;
                                    rd_argmax <= 1;
                                    resp_len <= 10;
                                end
                                default: ;
                            endcase
                            if (command != CMD_COMPUTE) resp_valid <= 1;
                            state <= PKT_RESPOND;
                        end
                    end
                    PKT_RESPOND: begin
                        if (wait_compute) begin
                            if (compute_done) begin
                                wait_compute <= 0;
                                resp_valid <= 1;
                            end
                        end else if (resp_valid && resp_ready) begin
                            resp_valid <= 0;
                            state <= PKT_HUNT;
                        end
                    end
                    default: state <= PKT_HUNT;
                endcase
            end
        end
    end
endmodule : packet_parser
